SELECT b.id, b.billing_year AS billingYear, b.total_consumption AS totalConsumption, b.bill_amount AS billAmount, b.paid_amount AS paidAmount, b.paid_time AS paidTime, b.payment_method AS paymentMethod, b.arrears_amount AS arrearsAmount, b.payment_status AS paymentStatus, b.generate_time AS generateTime, b.reminder_count AS reminderCount, b.payment_deadline AS paymentDeadline, b.current_reading AS currentReading, b.previous_reading AS previousReading, b.meter_reading_time AS meterReadingTime, b.meter_id AS meterId, b.customer_id AS customerId, c.customer_name AS customerName, c.electricity_category AS electricityCategory FROM electricity_bill b LEFT JOIN electricity_customer c ON b.customer_id = c.id AND c.deleted = 0
b.deleted = 0
AND b.billing_year = #{billingYear}
AND b.payment_status = #{paymentStatus}
AND b.meter_id = #{meterId}
AND c.customer_name LIKE CONCAT('%', #{customerName}, '%')
AND b.total_consumption >= #{minConsumption}
AND b.total_consumption <= #{maxConsumption}
ORDER BY b.billing_year DESC, b.create_time DESC

SELECT * FROM electricity_bill

    deleted = 0

        AND billing_year = #{billingYear}


        AND payment_status = #{paymentStatus}


ORDER BY ${sortField} ${sortOrder} LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM electricity_bill

    deleted = 0

        AND billing_year = #{billingYear}


        AND payment_status = #{paymentStatus}

SELECT * FROM electricity_bill

    deleted = 0
    AND customer_id = #{customerId}

        AND billing_year = #{billingYear}


        AND payment_status = #{paymentStatus}


ORDER BY billing_year DESC, create_time DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM electricity_bill

    deleted = 0
    AND customer_id = #{customerId}

        AND billing_year = #{billingYear}


        AND payment_status = #{paymentStatus}
